mapper.update:
UPDATE course_teacher


        course_id = (SELECT id FROM course WHERE course_name = #{courseName}),


        teacher_id = #{teacherId},


        clazz_id = #{clazzId}


WHERE course_id = #{id}

mapper.select:
SELECT c.id, c.course_name, c.create_time, ct.teacher_id, ct.clazz_id, u.name AS teacherName FROM course c INNER JOIN course_teacher ct ON c.id = ct.course_id LEFT JOIN user u ON ct.teacher_id = u.id
AND ct.teacher_id = #{teacherId} AND ct.clazz_id = #{clazzId}
GROUP BY c.id, c.course_name, c.create_time, ct.teacher_id, ct.clazz_id, u.name LIMIT #{offset}, #{pageSize}

SELECT COUNT(DISTINCT c.id)
FROM course c
INNER JOIN course_teacher ct ON c.id = ct.course_id

    AND ct.teacher_id = #{teacherId}
    AND ct.clazz_id = #{clazzId}
